package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.OvertimeRequest; import EmployeeManagementSystem.repository.OvertimeRequestRepository; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class OvertimeRequestServiceImpl implements OvertimeRequestService{
 private final OvertimeRequestRepository repo; public OvertimeRequestServiceImpl(OvertimeRequestRepository r){repo=r;}
 public List<OvertimeRequest> my(String u){return repo.findByUserIdOrderByWorkDateDescCreatedAtDesc(u);} public List<OvertimeRequest> all(){return repo.findAllByOrderByWorkDateDescCreatedAtDesc();}
 public OvertimeRequest create(OvertimeRequest x,String u,String n){if(x.getWorkDate()==null)throw new IllegalArgumentException("Work date is required."); if(x.getHours()==null||x.getHours()<=0||x.getHours()>24)throw new IllegalArgumentException("Hours must be between 0 and 24."); if(x.getWorkDate().isAfter(LocalDate.now()))throw new IllegalArgumentException("Work date cannot be in the future."); if(repo.existsByUserIdAndWorkDateAndStatusIn(u,x.getWorkDate(),List.of("SUBMITTED","UNDER_REVIEW","APPROVED")))throw new IllegalArgumentException("An active overtime request already exists for this date."); x.setId(null);x.setRequestNumber("OT-"+System.currentTimeMillis());x.setUserId(u);x.setEmployeeName(n);x.setStatus("SUBMITTED");x.setReviewerUserId(null);x.setReviewerComment(null);x.setReviewedAt(null);if(x.getCompensationMode()==null)x.setCompensationMode("PAYMENT");if(x.getCompOffDays()==null)x.setCompOffDays(0.0);return repo.save(x);}
 public OvertimeRequest review(Long id,String s,String c,String r){OvertimeRequest x=repo.findById(id).orElseThrow(()->new NoSuchElementException("Overtime request not found."));if(!Set.of("APPROVED","REJECTED","UNDER_REVIEW").contains(s))throw new IllegalArgumentException("Invalid review status.");x.setStatus(s);x.setReviewerUserId(r);x.setReviewerComment(c);x.setReviewedAt(LocalDateTime.now());return repo.save(x);}
}
